def shortest_path(graph, start, end):
    if start == end:
        return [start]
    queue = [(start, [start])]
    seen = set()
    while queue:
        node, path = queue.pop(0)
        if node == end:
            return path
        if node in seen:
            continue
        seen.add(node)
        for neighbor in graph.get(node, []):
            queue.append((neighbor, path + [neighbor]))
    return []

