from datetime import date

def add_months(text, months):
    value = date.fromisoformat(text)
    new_month = value.month + months
    new_year = value.year + new_month // 12
    new_month = new_month % 12 or 12
    try:
        new_day = min(value.day, (date(new_year, new_month + 1, 1) - date(new_year, new_month, 1)).days)
    except ValueError:
        new_day = (date(new_year, new_month, 1) - date(new_year, new_month - 1, 1)).days
    return date(new_year, new_month, new_day).isoformat()

