def rke_encode(text):
    """Encode a string using run-length encoding.

    Returns a list of [character, count] pairs for each maximal
    substring of identical characters. An empty input returns [].
    """
    result = []
    previous = None
    count = 0

    for char in text:
        if char != previous:
            if count:
                result.append([previous, count])
            previous = char
            count = 1
        else:
            count += 1

    # Append the final run if any characters were processed
    if count:
        result.append([previous, count])

    return result


